import { ok, fail } from './result.js';
import { roundCents } from './money.js';
import { getCustomer, TIER_DISCOUNTS, normalizeId } from './customers.js';
import { getProduct } from './catalogue.js';
import { nextInvoiceNumber } from './numbering.js';

/**
 * Validate discount percent value.
 * @param {any} discountPercent
 * @returns {boolean}
 */
function isValidDiscount(discountPercent) {
  return discountPercent != null && typeof discountPercent === 'number' && discountPercent >= 0 && discountPercent <= 100;
}

/**
 * Create a new invoice.
 * @param {{ customerId: string, issueDate: string, lines: Array<{ sku: string, qty: number, discountPercent?: number }> }} input
 * @returns {{ ok: true, value: { customerId: string, issueDate: string, status: string, lines: Array } } | { ok: false, error: string }}
 */
export function createInvoice({ customerId, issueDate, lines }) {
  // Normalize and validate customer
  const normalizedCustomerId = normalizeId(customerId);
  const customerResult = getCustomer(normalizedCustomerId);
  if (!customerResult.ok) return customerResult;

  // Validate date format (YYYY-MM-DD)
  if (!/^\d{4}-\d{2}-\d{2}$/.test(issueDate)) {
    return fail('DATE_INVALID');
  }
  const date = new Date(issueDate + 'T00:00:00Z');
  if (isNaN(date.getTime())) {
    return fail('DATE_INVALID');
  }

  // Validate lines array is not empty
  if (!Array.isArray(lines) || lines.length === 0) {
    return fail('NO_LINES');
  }

  // Validate and build each line
  const invoiceLines = [];
  const customer = customerResult.value;
  for (const line of lines) {
    // Validate quantity
    if (!Number.isInteger(line.qty) || line.qty <= 0) {
      return fail('QTY_INVALID');
    }

    // Determine discount percent: explicit value always wins, otherwise use tier discount
    let discountPercent;
    if (Object.prototype.hasOwnProperty.call(line, 'discountPercent')) {
      // Line has explicit discountPercent
      if (!isValidDiscount(line.discountPercent)) {
        return fail('DISCOUNT_INVALID');
      }
      discountPercent = line.discountPercent;
    } else {
      // Use tier discount
      discountPercent = TIER_DISCOUNTS[customer.tier] ?? 0;
    }

    // Validate SKU exists and get product details
    const productResult = getProduct(line.sku);
    if (!productResult.ok) return productResult;

    const product = productResult.value;
    invoiceLines.push({
      sku: line.sku,
      name: product.name,
      qty: line.qty,
      unitPrice: product.unitPrice,
      vatRate: product.vatRate,
      discountPercent,
    });
  }

  return ok({
    customerId,
    issueDate,
    status: 'draft',
    lines: invoiceLines,
  });
}

/**
 * Calculate the total amount for a single line item.
 * @param {{ qty: number, unitPrice: number }} line
 * @returns {number} total in cents
 */
export function lineTotal(line) {
  return roundCents(line.qty * line.unitPrice);
}

/**
 * Calculate the discount amount for a single line item.
 * @param {{ qty: number, unitPrice: number, discountPercent?: number }} line
 * @returns {number} discount in cents, clamped at 0
 */
export function lineDiscount(line) {
  const discountPercent = line.discountPercent ?? 0;
  const total = lineTotal(line);
  const discount = roundCents((total * discountPercent) / 100);
  return Math.max(0, discount);
}

/**
 * Calculate the VAT amount for a single line item.
 * @param {{ qty: number, unitPrice: number, discountPercent?: number, vatRate: number }} line
 * @returns {number} VAT in cents, clamped at 0
 */
export function lineVAT(line) {
  const total = lineTotal(line);
  const discount = lineDiscount(line);
  const taxableAmount = Math.max(0, total - discount);
  const vat = roundCents((taxableAmount * line.vatRate) / 100);
  return Math.max(0, vat);
}

