  assert.equal(lineTotal({ qty: 100, unitPrice: 50 }), 5000);
});

test('invoiceTotals calculates subtotal and total for single line', () => {
  const invoice = {
    lines: [{ qty: 5, unitPrice: 8500, discountPercent: 0, vatRate: 21 }],
  };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 42500);
  assert.equal(totals.vat, 8925);
  assert.equal(totals.total, 51425);
});

test('invoiceTotals sums multiple line items', () => {
  const invoice = {
    lines: [
      { qty: 5, unitPrice: 8500, discountPercent: 0, vatRate: 21 },
      { qty: 2, unitPrice: 980, discountPercent: 0, vatRate: 21 },
      { qty: 1, unitPrice: 120000, discountPercent: 0, vatRate: 21 },
    ],
  };
  const totals = invoiceTotals(invoice);
  const expectedSubtotal = 42500 + 1960 + 120000;
  const expectedVAT = Math.round((42500 * 21) / 100) + Math.round((1960 * 21) / 100) + Math.round((120000 * 21) / 100);
  assert.equal(totals.subtotal, expectedSubtotal);
  assert.equal(totals.vat, expectedVAT);
  assert.equal(totals.total, expectedSubtotal + expectedVAT);
});

test('invoiceTotals handles empty lines', () => {
  const invoice = { lines: [] };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 0);
  assert.equal(totals.total, 0);
});

test('invoiceTotals works with invoice from createInvoice', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 3 },
      { sku: 'ICON-SET', qty: 2 },
    ],
  });
  const totals = invoiceTotals(r.value);
  const expectedSubtotal = 3 * 8500 + 2 * 980;
  const expectedDiscount = Math.round((3 * 8500 * 5) / 100) + Math.round((2 * 980 * 5) / 100);
  const line1Total = 3 * 8500 - Math.round((3 * 8500 * 5) / 100);
  const line2Total = 2 * 980 - Math.round((2 * 980 * 5) / 100);
  const expectedVAT = Math.round((line1Total * 21) / 100) + Math.round((line2Total * 21) / 100);
  assert.equal(totals.subtotal, expectedSubtotal);
  assert.equal(totals.discount, expectedDiscount);
  assert.equal(totals.vat, expectedVAT);
  assert.equal(totals.total, expectedSubtotal - expectedDiscount + expectedVAT);
});

test('addLine adds a new line to an invoice', () => {
  const invoice = createInvoice({
