});

test('invoiceTotals with tier discount and VAT', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 10 }],
  });
  const totals = invoiceTotals(r.value);
  const expectedSubtotal = 10 * 8500;
  const expectedDiscount = Math.round((expectedSubtotal * 5) / 100);
  const expectedVAT = Math.round(((expectedSubtotal - expectedDiscount) * 21) / 100);
  assert.equal(totals.subtotal, expectedSubtotal);
  assert.equal(totals.discount, expectedDiscount);
  assert.equal(totals.vat, expectedVAT);
  assert.equal(totals.total, expectedSubtotal - expectedDiscount + expectedVAT);
});

test('invoiceTotals with explicit discount and VAT', () => {
  const invoice = {
    lines: [{ qty: 100, unitPrice: 1000, discountPercent: 15, vatRate: 21 }],
  };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 100000);
  assert.equal(totals.discount, 15000);
  const expectedVAT = Math.round(((100000 - 15000) * 21) / 100);
  assert.equal(totals.vat, expectedVAT);
  assert.equal(totals.total, 100000 - 15000 + expectedVAT);
});
